from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaObject, SchemaField


class Carrier(SchemaObject):
    local_cell_resource_id = SchemaField(name="lcr_id")
    config_mo_url = SchemaField(name="channel_dn.href")
    channel_properties = SchemaField(name="channel_properties")

    def __init__(self, local_cell_resource_id, config_mo_url, channel_properties):
        """
        :param local_cell_resource_id: Local cell resource ID which client can get from the mapped cell's lcrId in plan
        :param channel_properties
        """
        self.config_mo_url = config_mo_url
        self.local_cell_resource_id = local_cell_resource_id
        self.channel_properties = channel_properties

        super(Carrier, self).__init__()
